<script lang="ts">
  import { useDemo } from '#lib/demo.svelte';
  let { target }: { target: string } = $props();
  const demo = useDemo();
  let open = $state(false);
  let text = $state('');
  let stars = $state(5);
  let photo = $state('');
  let withPhoto = $state(false);
  const reviews = $derived(demo.state.reviews.filter((r) => r.target === target && (!withPhoto || r.photo)));
  function photoChange(e: Event) { const file = (e.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 500000) { demo.notice = demo.t('Usa una imagen de menos de 500 KB para la demo local.', 'Use an image under 500 KB for the local demo.'); return; } const reader = new FileReader(); reader.onload = () => photo = String(reader.result); reader.readAsDataURL(file); }
</script>
<section id="valoraciones"><div class="row between"><h2>{demo.t('Valoraciones de demostración', 'Demo reviews')}</h2><button class="secondary" onclick={() => open = !open}>{demo.t('Escribir una valoración', 'Write a review')}</button></div><p class="muted">{demo.t('No son opiniones de compradores reales. Las nuevas valoraciones se guardan solo en tu navegador.', 'These are not real customer opinions. New reviews are only saved in your browser.')}</p><label class="check"><input type="checkbox" bind:checked={withPhoto}/>{demo.t('Solo con foto', 'With photo only')}</label>{#if open}<form class="callout" onsubmit={(e) => { e.preventDefault(); demo.state.reviews.push({ target, text, stars: Number(stars), photo }); text = ''; photo = ''; open = false; demo.notice = demo.t('Valoración local guardada', 'Local review saved'); }}><label>{demo.t('Estrellas', 'Stars')}<select bind:value={stars}>{#each [5,4,3,2,1] as n}<option value={n}>{n} ★</option>{/each}</select></label><label style="margin:15px 0">{demo.t('Tu comentario demo', 'Your demo comment')}<textarea required bind:value={text} maxlength="1000"></textarea></label><label>{demo.t('Foto local opcional (máx. 500 KB)', 'Optional local photo (max. 500 KB)')}<input type="file" accept="image/*" onchange={photoChange}/></label><button style="margin-top:18px">{demo.t('Guardar localmente', 'Save locally')}</button></form>{/if}<div class="grid cols-2" style="margin-top:22px">{#each reviews as review}<article class="card card-body"><strong>{'★'.repeat(review.stars)} · DEMO</strong><p>{review.text}</p>{#if review.photo}<img class="review-photo" src={review.photo} alt={demo.t('Foto aportada a la demo', 'Photo added to the demo')}/>{/if}</article>{:else}{#if !withPhoto}<article class="card card-body"><strong>★★★★★ · {demo.t('Ejemplo ficticio', 'Fictional example')}</strong><p>{demo.t('Me ha servido poder seguir el orden de las cuatro fases en el prototipo.', 'Being able to follow the four phases in the prototype was helpful.')}</p></article>{:else}<p>{demo.t('No hay valoraciones locales con foto.', 'No local photo reviews yet.')}</p>{/if}{/each}</div></section>
